const __pageData = JSON.parse('{"title":"12.2 SLAM Mapping and Navigation","description":"","frontmatter":{},"headers":[],"relativePath":"docs/12.2 SLAM Mapping and Navigation.md","filePath":"docs/12.2 SLAM Mapping and Navigation.md"}');
